"sc73w6": "Deine Funke hat keine Tasten, die dieser Browser sehen kann",
"uo8hw2": "Jeder Schalter kommt als Achse an, also kann noch nichts daran Enter drücken. Halte einen beliebigen Stick etwa eine Sekunde aus der Mitte, das zählt als ein Tastendruck und reicht, um hierher zu kommen und es richtig zu beheben. Am Ende der Kalibrierung legst du den Schalter um, den du als Enter willst, und danach funktioniert er wie eine Taste.",
"1k7x574": "Deine Kalibrierung liest {0} von einer Achse, die diese Funke nicht hat",
