"53c27k": "die zurückfedert. Die Kalibrierung dauert etwa eine Minute und behebt es dauerhaft.",
"1est9fl": "Dieser Browser sieht deinen Gier-Stick nicht",
"1agkf6n": "Die Achse, die er für Gieren hielt, hat sich kein einziges Mal bewegt, während ein Stick, den er nicht kennt, von Anschlag zu Anschlag bewegt wurde. Die Funke meldet ihre Kanäle also in einer anderen Reihenfolge als angenommen, und was dir fehlt, ist Gieren. Die Kalibrierung dauert etwa eine Minute und sagt dieser Seite, welche Achse welche ist.",
"x7203j": "Dieser Browser hält dein Gas für Gieren",
"1m52vjm": "Die Achse, die er als dein Gas liest, federt beim Loslassen zur Mitte zurück, was ein Gas nie tut, und die Achse, die er als Gieren liest, bleibt, wo man sie lässt, was nur ein Gas tut. Dein Gas dreht den Quad also, statt ihn zu heben. Die Kalibrierung dauert etwa eine Minute und sagt dieser Seite, welche Achse welche ist.",
"5fqwjo": "Dieser Browser hält deine Funke für ein Gamepad",
"y5c806": "Eine ihrer Stick-Achsen ruht außerhalb der Mitte und bleibt dort, was ein Gamepad-Stick nie tut und das Gas einer Funke immer. Als Gamepad gelesen landen ihre Sticks auf den falschen Kanälen. Die Kalibrierung dauert etwa eine Minute und sagt dieser Seite, welche Achse welche ist.",
"11e2cn1": "Am Handy ist die wahrscheinlichste Ursache, dass Chrome nur vier Achsen der Funke weitergibt.",
"ehzk3y": "Auf Low würde der Timer die Bilder zeichnen, während du fliegst, aber dieser Bildschirm aktualisiert so schnell wie der Timer zeichnen kann oder schneller, also wurden Bilder doppelt gezeigt: Bis die Seite neu geladen wird, gibt der Bildschirm den Takt vor. Timer, immer behält den Timer trotzdem.",
"vl1tj": "Der Timer zeichnet die Bilder in jedem Preset, während du fliegst: Das Bild reagiert schneller auf die Sticks, für mehr GPU-Arbeit, Wärme und Akku, und die Auto-Grafik hält währenddessen still. Replays und Filme bleiben im Takt des Bildschirms.",
"qi0jq2": "Der Bildschirm gibt in jedem Preset den Takt der Bilder vor, der normale Takt des Browsers: am schonendsten für den Akku, und das Bild wartet auf die nächste Aktualisierung.",
"1du9pl5": "Auf Low zeichnet der Timer die Bilder, während du fliegst, das Bild reagiert also schneller auf die Sticks, für mehr GPU-Arbeit, Wärme und Akku; die Auto-Grafik hält währenddessen still, und Replays und Filme bleiben im Takt des Bildschirms. Auf Medium und High gibt der Bildschirm alles vor.",
