"stn2d9": "Wie weit die Sticks gehen und wie scharf. Deine, nicht die des Tunes. Eine Funke in Acro fliegt diese Kurve; Tastaturrennen starten in Angle. Eine Änderung mitten im Lauf lässt den Quad, wo er ist, und die Uhr läuft weiter.",
"1m2xvti": "Flugmodus",
"xjyq13": "Acro: Die Sticks sind Drehraten, loslassen hält die Lage. Angle: Die Sticks sind Neigung bis zu Betaflights 60-Grad-Grenze, loslassen richtet aus. Dieses Rennen wird mit der Tastatur geflogen, die ihre eigene Wahl hat (Tastaturrennen, unter Quad); diese Zeile ändert genau die. M im Flug schaltet auch um.",
"1r5ubv6": "Acro: Die Sticks sind Drehraten, loslassen hält die Lage. Angle: Die Sticks sind Neigung bis zu Betaflights 60-Grad-Grenze, loslassen richtet aus, Gieren bleibt eine Rate. Flips und Rolls brauchen Acro. M im Flug schaltet auch um und merkt es sich.",
"x7vih9": "Wie viele pro Seite, wie gut die Bots spielen und wann es endet.",
"17g8v9b": "Flieg hier allein weiter, ohne Bots und ohne Uhr.",
"11br69w": "Bots, und wie gut sie filmen.",
"m20i5w": "Film hier allein weiter, ohne Bots.",
"c8vuhg": "Der Warteraum: die Bots, wie gut jeder ist, die Runde und der Vorsprung.",
"5typne": "Flieg die Schule allein, ohne Bots.",
"1afdza": "Bots, wie gut sie treiben und wann die Runde endet.",
"1t8ovw1": "Treib hier allein weiter, ohne Bots und ohne Uhr.",
"1087r08": "Bots, wie gut sie sind, wie lang die Bänder sind und die Runde.",
"1206cs3": "Flieg hier weiter, ohne Bänder und ohne Bots.",
"899bgs": "Bots, wie gut sie sind, die Runde und wie hart Treffer sind.",
"172ev2t": "Flieg hier weiter, ohne Waffen und ohne Bots.",
"1w5pf1h": "Tasten für Kanone und Rakete",
"14d24dx": "Wähl für jede eine Taste oder einen Schalter und teste sie.",
"d2okc9": "Zurück zu den Minispielen",
"j88ayy": "Weiter",
"jsscfj": "Fühlt es sich falsch an?",
"1emvcwj": "Wie weit die Sticks gehen, und das Gaslimit. Eine Änderung hier lässt den Quad, wo er ist, und die Uhr läuft weiter.",
"17lkkrv": "Sonstiges",
"1sc5qgc": "Dein Name, deine Funke, Grafik und Sound.",
"6gxuho": "Beendet {0}.",
"wyh1np": "Wie schwer sich der Quad anfühlt. Rechts ist schwerer: Er fällt, wenn du das Gas wegnimmst, und hängt nicht mehr oben im Sprung. Links ist leichter, und er schwebt. {0} ist der Quad im Auslieferungszustand; eine Änderung mitten in der Runde macht die Runde ungültig, und eine Runde abseits von {1} kommt mit ihrem Gewicht neben deinem Namen aufs öffentliche Board.",
"1ayl725": "Luftgriff",
"6bttpz": "Wie stark die Luft den Quad bremst, also wie weit er mit zentrierten Sticks weitergleitet. Links gleitet er weiter und wird schneller; rechts greift die Luft, er stoppt früher und die Höchstgeschwindigkeit sinkt. {0} ist der Quad im Auslieferungszustand, festgelegt anhand der Tunes, die Piloten geschickt haben. Eine Änderung mitten in der Runde macht die Runde ungültig, und eine Runde abseits von {1} geht mit dem Tag Tuned aufs öffentliche Board.",
"ior56v": "Motorleistung",
"1x4irmq": "Wie viel Drehzahl die Motoren pro Volt machen, ihr KV. Links ist sanfter: ein milderer Punch und weniger Höchstgeschwindigkeit. Rechts ist kräftiger, dafür bricht der Akku stärker ein, und der Quad schwebt tiefer auf dem Stick. {0} ist der Quad im Auslieferungszustand, festgelegt anhand der Tunes, die Piloten geschickt haben. Eine Änderung mitten in der Runde macht die Runde ungültig, und eine Runde abseits von {1} geht mit dem Tag Tuned aufs öffentliche Board.",
"1bsvonq": "Standardmäßig aus. Eingeschaltet erscheinen {0} neben Gewicht zwischen den Sticks, solange der Quad am Boden steht, und ein Flug mit deinen eigenen Reglern endet mit einer Frage: Hat sich das besser angefühlt als der Standard-Quad? Nichts wird gesendet, wenn du nicht Ja sagst. Ausgeschaltet fliegt der Quad im Auslieferungszustand, egal was die Regler sagen. Umschalten mitten in der Runde macht die Runde ungültig, wenn es den Quad ändert, den du fliegst.",
"5xvgod": "Nach einem getunten Flug fragen",
"1siorg1": "Wenn ein Flug mit deinen eigenen Reglern endet, wird gefragt, ob er sich besser anfühlte als der Standard. Du kannst immer Nein sagen, und ohne Ja wird nichts gesendet. Ausgeschaltet wird nie gefragt; die Regler funktionieren trotzdem.",
"187fv0s": "Sag der Tune-Arbeit, wie der Quad fliegt. Ein Wort reicht; dein Tune, deine PID-Anpassung und deine Rates gehen mit.",
"16us7mj": "Sprache",
"2nnvct": "Die Sprache der Menüs. Das Spiel startet neu, um sie anzuwenden.",
"1hmyggy": "{0} wurde auf diesem Rechner ausprobiert und hat das Bild nicht rechtzeitig geliefert, also bleibt Auto bei {1} oder darunter.",
"s4dnb5": "Auto: zeichnet mit {0}{1}. Es beobachtet, wie die Bilder tatsächlich ankommen, senkt die Auflösung, wenn das Bild zu spät kommt, und wechselt das Preset zwischen den Läufen.{2} Wähl ein Preset, um es von Hand festzulegen.",
"1ejndm0": "Grafik",
"dcm8ea": "Zeichnet jedes Bild direkt auf den Bildschirm, statt es hinter der Seite einzureihen. Das kann ein, zwei Bilder von der Zeit zwischen deinen Sticks und dem Bild abziehen. Es kann zu Tearing kommen.",
"1ttxrpl": "Aus ab dem nächsten Laden. {0} Dieser Browser nutzt es, bis du neu lädst.",
"1j0ql37": "Aus. {0} Lade neu, nachdem du es eingeschaltet hast.",
"o73nnv": "Die Steam-Edition kann ohne VSync laufen.",
"101as9w": "der Bildschirm aktualisiert mit {0} Hz",
"cfutp1": "die GPU braucht etwa {0} ms länger als ein Bild",
"gtjdfs": "Die Ansicht mit niedriger Latenz ist aktiv",
"1ampkwb": "Wenn dieser Monitor mehr als 60 Hz kann, prüfe, ob das System auf die höchste Bildwiederholrate eingestellt ist (Windows: Einstellungen, Anzeige, Erweiterte Anzeige), denn die Seite kann nur so oft zeichnen wie der Bildschirm, den sie bekommt.",
"13d5h9g": "Eingabe bis Bildschirm",
"9anx43": "Hier nicht messbar",
"57y603": "Drück ein paar Tasten",
"ks1elk": "Etwa {0} ms",
"12jryem": "Wird erkannt",
"h5se6q": "Aus dem WebGL-Kontext gelesen, der die Welt zeichnet.",
"jgkrww": "Schließ eine Funke im Joystick-Modus an. Wenn mehr als eine angeschlossen ist, wählst du hier, welche fliegt.",
"1y6zyev": "Ein Gerät ist angeschlossen, {0}. Öffne das hier, um es zu bestätigen oder zur Tastatur zu wechseln.",
"1a5n4iv": "{0} Geräte sind angeschlossen. Beweg das, das du willst. Windows listet sie in der Reihenfolge der Gamecontroller; auf diesem Bildschirm wählst du.",
"hkrgl0": "Eine Strecke mit Toren auf einem Feld im Freien, gegen die Uhr. Ein großer, schneller Renn-Quad, und jede Runde, die du beendest, kann aufs öffentliche Board.",
"1rnl54t": "Dieselbe Uhr, drinnen. Ein winziger Whoop mit Ducts auf einer Strecke, die in ein Wohnzimmer passt.",
"1kaa7l9": "Jede Freestyle-Karte: die Stadt, die Häuser von Nick Burns, Heads und Joshua Bardwell, Thomas More's Shop, Sunnyfield, Shiokaze Point, Hibari Yard und jede Karte, die Piloten gebaut und auf dem Board veröffentlicht haben. Keine Uhr, keine Tore, und Tricknamen sind ein Schalter darin.",
"tn5ckg": "Editor",
"19ybx9k": "Bau deine eigene. Eine Rennstrecke für den Fünf-Zoll, einen Raum für den Whoop oder eine Freestyle-Karte mit Bandos, Kränen und benannten Gaps, von oben gezeichnet und von derselben Seite aus geflogen.",
"1rjxeiy": "Vom ersten Schweben bis zur Pro-Lizenz. Lern fliegen, hol dir deine Rookie-Lizenz, dann arbeite dich im Skill-Baum durch Rennen oder Freestyle. Fang hier an, wenn du noch nie geflogen bist.",
