"1uvpjn8": "Trickliste",
"10sqi3d": "Jeder Trick, den die Wertung benennen kann, was er bringt und wie er aussieht. Wähl einen und sieh ihn dir an: Das Bild entsteht aus derselben Definition, mit der die Wertung vergleicht, du siehst also genau das, worauf sie wartet. Jeder wurde im Test geflogen und gewertet, das verdient ihm den Platz hier. Punkte gelten vor der Combo, die sie multipliziert.",
