"10nopfd": "Sichtfeld",
"unl4q1": "Breiter zeigt mehr, schmaler vergrößert. Schmal entspricht dem, was eine FPV-Linse mit der Bildmitte macht; Standard gibt etwas davon für Breite zurück; Am breitesten ist so breit, wie dieses Bild ehrlich gehen kann, und die Tore wirken dadurch kleiner.",
"4emmbg": "Fischauge",
"1u80da4": "Biegt das Bild so, wie es eine echte FPV-Linse tut: Die Ecken bleiben, wo das Sichtfeld sie hinsetzt, die Ränder rücken zusammen und die Mitte wird größer. Aus ist ein gerades, unverzerrtes Bild. Wenn dir weite Ansichten Übelkeit machen, probier Leicht oder Mittel und nimm ein breiteres Sichtfeld, um die Breite zurückzuholen.",
"1ir4yll": "Kamerawinkel",
"6gsnw2": "Wie weit die Kamera gegenüber dem Rahmen nach oben geneigt ist. {0} ist flach, mit Blick entlang der Nase. {1} ist typisches Cruisen. 45 bis {2} ist Rennen. Ab etwa 30 beginnt Gieren, den Horizont zu rollen: Bei {3} Grad zeigen sich {4} Prozent eines Gierens als Rollen im Bild. Das macht eine echte geneigte Kamera so. Senk die maximale Gier-Rate im Rates-Bildschirm, um es zu zähmen.",
"1vp9w8f": "Gieren wird den Horizont rollen",
"1hjxoj1": "Bei {0} Grad Neigung zeigen sich {1} Prozent eines Gierens als Rollen im Bild: {2} deg/s davon bei deiner Gier-Rate von {3} deg/s. Das macht eine echte geneigte Kamera so, und die übliche Antwort ist langsameres Gieren. Die maximale Gier-Rate auf {4} zu senken bringt es zurück auf {5} deg/s. Du kannst sie jederzeit im Rates-Bildschirm ändern.",
"1f9wwkb": "Diese Meldung behalten?",
"v5eaek": "Du hast etwas geschrieben, das noch nicht gesendet wurde. Hier wird kein Entwurf gespeichert, beim Schließen geht es also verloren.",
