"nnhdr0": "Er ist für den {0}, also wechselst du zu diesem Fluggerät und seiner eigenen Streckenklasse.",
"1axqv1t": "Er verändert Luftgriff oder Motorleistung, also wird Fluggefühl einstellen eingeschaltet, und eine damit geflogene Runde geht mit dem Tag Tuned aufs öffentliche Board.",
"t9yl6f": "Seine Betaflight-Einstellungen ersetzen Deine Änderungen an diesem Fluggerät, bis du deine zurückholst.",
"f50exw": "Deine Grafik, Sticks, Funke und Rundenzeiten bleiben unberührt.",
"1e5r0vj": "Dieser Build kann diesen Tune nicht fliegen. Vielleicht ist er für ein später hinzugefügtes Fluggerät.",
"1os1q6k": "Dieser Tune baut auf einem Betaflight-Tune auf, den dieser Build nicht hat.",
