"2qyb3f": "Wie fliegt er?",
"1x4knm": "Ein ehrliches Wort lenkt die Tune-Arbeit mehr als jede Telemetrie. Nur die erste Zeile ist nötig; dein Tune, deine PID-Anpassung und deine Rates reisen mit der Antwort, damit auch die Zahlen hinter dem Gefühl ankommen. Du bist {0} geflogen.",
"1yc8yfn": "Der Gewichtsregler zwischen den Sticks im Flugbildschirm ist genau für diese Beschwerde da: Er skaliert das Gewicht, das der Quad trägt, also fällt er, wenn du das Gas wegnimmst, statt zu hängen. Deiner steht bei {0} Prozent. Weiter rechts fällt er schneller, wenn du das Gas wegnimmst, und steigt nach einem kurzen Punch weniger nach. Der Schwebepunkt wandert auf dem Stick mit nach oben, von {1} Prozent im Standard auf {2} bei {3}. Zieh ruhig daran, bevor du auf uns wartest, und eine damit geflogene Runde kommt mit ihrem Gewicht neben deinem Namen aufs öffentliche Board.",
"r74boy": "Dieser Quad schwebt ohne Gaslimit bei {0} Prozent Stick, also liegt fast der ganze Weg über dem Schwebepunkt. Rates, Gaslimit, 75 Prozent verschiebt das Schweben auf {1} Prozent und gibt die Feinkontrolle zurück, ohne Steigleistung zu verlieren, die du drinnen nutzen kannst. Einen Versuch wert, bevor du auf uns wartest.",
"1xpffsm": "Fluggefühl einstellen einschalten",
"194uxup": "Fluggefühl einstellen ist an. Solange du gelandet bist, {0} {1} neben Gewicht zwischen den Sticks. Wenn sich eine Einstellung besser anfühlt als der Standard, wirst du am Ende des Flugs gefragt, ob du sie senden willst.",
"1elhpti": "Willst du es selbst ändern? Fluggefühl einstellen setzt {0} neben Gewicht, solange du am Boden bist: {1}. Wenn sich eine Einstellung besser anfühlt als der Standard, kannst du uns die Zahlen nach dem Flug schicken. Aus, bis du es einschaltest, und ohne dein Ja wird nichts gesendet.",
"15h6xkr": "In deinen eigenen Worten (optional)",
"1m200ro": "Was du der Person mit dem Schraubenzieher sagen würdest.",
"1d67zxc": "Der Quad fühlte sich",
"ghfh85": "Etwas Bestimmtes (beliebig viele)",
"z5wkkb": "Wähl ein Wort in der ersten Zeile. Eins reicht.",
