"120kk3i": "Angekommen, mit deinem Tune und deinen Rates im Gepäck. Genau das bewegt das Flugmodell.",
"frbrff": "Tune gesendet",
"yigmhv": "Dieser Tune ist auf dem Board. Danke.",
"1xaroqk": "{0}, {1} in der Luft. Wenn es sich besser anfühlte als der Standard, schick die Zahlen mit ein, zwei Worten an die Leute, die den Sim tunen. Nichts wird gesendet, solange du nicht Senden drückst.",
"12j7air": "Fühlte sich das besser an als der Standard?",
"1qjshkq": "{0}. {1} in der Luft mit dem {2}.",
"1k9f9e0": "Wenn ja, kannst du diese Zahlen mit ein, zwei Worten an die Leute schicken, die den Sim tunen. Nichts wird gesendet, solange du im nächsten Bildschirm nicht Senden drückst.",
"lmpjg0": "Besser als der Standard",
"kertdk": "Gleich oder schlechter",
"bhqymg": "Nicht mehr fragen",
"159zlyr": "Danke, das ist gut zu wissen",
"1v1dzby": "Ein Tune, der sich gleich oder schlechter anfühlte, zeigt den Leuten, die den Sim tunen, wo es nicht langgeht. Dieses Ergebnis auch senden? Nichts wird gesendet, solange du es nicht sagst.",
"1vcax0y": "Dieses Ergebnis senden",
"13gi980": "Deinen Tune senden",
"pve1j9": "{0}. {1} in der Luft mit dem {2}. Das geht mit deinen Worten ans Board, gruppiert nach Fluggerät und Physikversion, damit die Leute, die den Sim tunen, sehen, was Piloten bevorzugen. Dein Tune, deine Rates und dieselben Details wie bei einer Fluggefühl-Meldung gehen mit.",
"wanvfr": "Was sich geändert hat, und was du der Person mit dem Schraubenzieher sagen würdest.",
