"ft8rhj": "Der Quad fühlte sich (optional)",
"vzfgv1": "Wähl, wie es sich im Vergleich zum Standard anfühlte. Eins reicht.",
"132k2mx": "Dein Tune ist angekommen{0}, mit den Zahlen, deinen Worten und der Physikversion. Die Leute, die den Sim tunen, lesen das nebeneinander.",
"gcrazo": "Das Board wurde noch nicht aktualisiert, um Tunes anzunehmen, also wurde nichts gesendet. Versuch es später noch einmal.",
