"vnp8lx": "{0} ist eine gute erste Arena. Jede Karte geht. Doppelklick auf eine Karte, oder wähle sie und drück Hier kämpfen.",
"10l1jzq": "Dogfight-Arena",
"ufax2r": "Wähle die nächste Karte des Raums",
"o1q3k9": "Alle stimmen ab, ob sie mitkommen oder bleiben. Doppelklick auf eine Karte, oder wähle sie und drück Raum hierher verlegen.",
