"dnnril": "Dieser Lauf ist auf dem {0}. Verlass ihn, um das Fluggerät zu wechseln.",
"hoxe62": "Noch keine Freestyle-Karten auf dem Board. Bau eine im Builder und veröffentliche sie.",
"1uqgn63": "Das Board antwortet nicht, also werden nur die Stadt und deine eigene Karte angezeigt.",
"o0cwwo": "{0} konnte nicht vom Board geladen werden.",
"seaqq": "Das Board antwortet nicht, also können seine Zeiten nicht gezeigt werden.",
"zc4ait": "Noch keine Drei-Runden-Zeit auf dieser Strecke. RaceGOW wertet drei Runden am Stück, und die erste gehört dir.",
"jax78i": "Noch keine Zeiten auf dieser Strecke eingetragen. Die erste gehört dir.",
"1xawzzq": "Gewicht {0}%",
"obojrp": "Vorschau nicht verfügbar.",
"pfuxer": "Weltvorschau",
"1889adu": "Strecke der Woche",
"96px0t": "{0}. {1} führt mit {2}. Die beste Runde bis Montag gewinnt die Woche.",
"z9xxt4": "{0}. Diese Woche hat noch niemand eine Runde darauf, also führt die erste.",
"9h1zsw": "Linker Daumen",
"l92ddx": "Rechter Daumen",
"11li9o0": "Die ganze Ecke",
"653lk2": "Das Pad ist größer als die Zeichnung: Der Stick ist dort, wo dein Daumen in der unteren Ecke landet, und der Ausschlag ist das Ziehen von dort.",
"c7cdxu": "Querformat",
"1cau3o4": "Dreh das Handy quer. Die Pads liegen unter beiden Daumen, so wie eine Funke in beiden Händen liegt.",
"b46ibj": "Turtle",
"4uqxss": "Wenn du kopfüber am Boden landest, erscheint der Hinweis TURTLE MODE. Gib auf dem rechten Pad Pitch oder Roll, um dich umzudrehen. Du musst es nicht timen. Lass los, dann heb ab.",
"1qyunph": "Der Pause-Chip, oben rechts. Treffer prallen ab. Zeit ist die Strafe. Mach weiter, dann gib Pitch oder Roll, falls du kopfüber liegst.",
"j3nmgx": "Flieg durch das, das pulsiert. Grün ist der Weg hindurch, Rot ist die falsche Seite.",
"lkidd0": "Linker Stick (Mode {0})",
"dgt1q3": "{0}. Stell den Mode an der Funke ein, diese Seite folgt ihm in den Einstellungen.",
"1a3en5u": "Stell die Funke auf Joystick-Modus, bevor du diese Seite lädst, und starte dann Sticks kalibrieren in den Einstellungen.",
"8pq8oh": "Pitch bewegt den Cursor, Roll rechts wählt aus, Roll links geht zurück. Nach einer Pause oder einem Zieleinlauf wartest du einen Moment mit ruhenden Sticks und hältst Roll einen Takt lang.",
"d45qj0": "Neustart",
"ezjsbi": "R auf der Tastatur, oder ein Schalter an der Funke: Einstellungen, Neustart-Schalter, dann leg ihn um.",
"o7cl2g": "Loslassen hält die Lage, in der du ihn gelassen hast. Jede Kurve muss wieder herausgeflogen werden.",
"etorb5": "Wenn du kopfüber am Boden landest, erscheint der Hinweis TURTLE MODE. Gib mit dem rechten Stick Pitch oder Roll, um dich umzudrehen. Du musst es nicht timen. Zentriere den Stick, dann heb ab.",
"1ri6cg": "Was es ist",
"14tfw5g": "Einschalten",
"1eqzli7": "Quad, Launch Control, An. Es bleibt aus, bis du es einschaltest. Dann drück L an der Startlinie, bevor du Gas gibst.",
"14cfpm3": "Winkel setzen",
"11n5q78": "Gas im Leerlauf. Neig nach vorn, bis das OSD etwa 30 bis 40 Grad zeigt. Zentriere den Stick. Die Motoren halten ihn.",
"1aa3oyb": "Gib Gas über etwa 20 Prozent. Das Halten löst sich, die Props greifen, und du fliegst. L noch einmal setzt es nach einem Start zurück.",
"14arqvb": "Pfeil nach oben ist Pitch nach vorn. W ist Gas. Launch Control schaltet dich für das Halten auf Acro, danach kommt dein eigener Modus zurück.",
"r89zwp": "Dieselbe Abfolge wie auf einem echten Board. L ist der Modusschalter. Feineinstellung von launch_angle_limit und launch_trigger_throttle_percent auf der Firmware-Werkbank, unter Quad.",
"1wrrqt3": "Wenn du am Start umkippst, übernimmt TURTLE MODE. Gib Pitch oder Roll zum Umdrehen. Du musst es nicht timen. Zentriere den Stick, drück dann L und starte noch einmal.",
"1x7j2uc": "Launch Control, wenn du es unter Quad eingeschaltet hast. Neigen, zentrieren, Vollgas.",
"1xmpyfk": "Schaltet im Flug zwischen Angle und Acro und behält die Wahl.",
"1eyul69": "R, dann Escape",
"1ns2uml": "Zurück an die Startlinie, und Pause.",
"1hg0wdz": "Wenn du kopfüber am Boden landest, erscheint der Hinweis TURTLE MODE. Gib mit den Pfeiltasten Pitch oder Roll, um dich umzudrehen. Du musst es nicht timen. Lass los, dann heb ab.",
"19jaz7h": "Melde einen Fehler oder gib Feedback. Pausiert, wenn du in der Luft bist, und öffnet dann das Formular.",
"1ogqofk": "Die Pads erscheinen im Flug, unter deinen Daumen.",
"1harh8g": "Beweg deine Sticks. Diese folgen der Funke.",
"149s8uu": "L macht es scharf. Neigen, zentrieren, Vollgas. Die Gimbals folgen weiter deinen Händen.",
"rt9bay": "Drück die Tasten. Diese folgen deinen Händen.",
"utog3i": "Daumensticks sind ein echter proportionaler Stick, also fliegen sie den Flugmodus, der unter Quad eingestellt ist: standardmäßig Acro, wie eine Funke. Angle ist sanfter, solange du lernst: Lass das rechte Pad los und der Quad richtet sich selbst auf.",
"1uqyqut": "Eine Funke fliegt standardmäßig Acro: Die Sticks verlangen eine Drehrate, und Loslassen verlangt keine, also hält der Quad die Lage, in der er gerade ist. Ändere es unter Flugmodus in Quad, oder mit M im Flug.",
"wtsp1v": "Standardmäßig aus, weil Vollgas aus dem Halten heftig ist und nicht jeder das will. Schalte es unter Quad ein, dann L auf dem Pad. Die grüne LAUNCH-Anzeige ist der Pitch-Winkel. Sie blinkt, wenn das Gas kurz vor dem Auslösen ist.",
"t0ww0i": "Tasten sind an oder aus, also ist die Haltezeit das Analoge: Ein Tippen bewegt den Stick ein wenig, Halten bleibt bei einem fliegbaren Wert, langes Halten geht auf voll. Rennen auf Tasten starten in Angle, also richtet Loslassen den Quad auf.",
"arpbtx": "Was du fliegst",
"1k22ek3": "Keine Tore, keine Runde, zwei Minuten",
"j7omzh": "Keine Tore, keine Runde, keine Uhr",
"1pcy84h": "Streckenrekord",
"1ihgoer": "Noch keine Runde aufgezeichnet",
"10gi4nt": "Noch kein Rekord",
"tkyf31": "Beste Runde, Tor für Tor",
"a6ppg": "Deine Runde, Tor für Tor",
"r92sb6": "Eine saubere Runde, also siehst du hier, woraus sie bestand. Flieg noch eine, und der Streifen zeigt, wo sie Zeit verloren hat.",
"2ba7i5": "Die meiste Zeit verloren bei {0}, {1} auf deine schnellste dort.",
"m2w5l7": "Deine schnellste an jedem Tor ergibt zusammen {0}.",
"99o174": "Deine beste Runde war an jedem Tor deine schnellste.",
"b21txc": "Jage {0}, {1} s schneller",
"1y2w48a": "Die {1} von {0} auf dem Board, die nächste Runde, die schneller ist als deine {2}, fliegt als Geist neben dir. Direkt an den Start.",
"ocljwq": "Schneller als jede aufgezeichnete Runde auf dem Board. Die {1} von {0} ist der Geist des Rekords, er fliegt neben dir, bleib vor ihm.",
"dj5y8q": "Lauf beendet",
"iabifn": "Keine saubere Runde in diesem Lauf. Den Boden oder einen Torrahmen zu treffen kostet die Zeit, die du brauchst, um wieder loszukommen. Nur ein Tor außer der Reihe macht die Runde ungültig und schickt dich zurück zum mintfarbenen Ring.",
