"1w2ka5l": "Keine ungültigen",
"146lnlx": "{0}{1} ist auf dem öffentlichen Board. Trag eine Zeit unter deinem Namen ein, um darauf zu erscheinen.",
"z120pj": "{0} ist deine Kopie{1}. Veröffentliche sie unter einem neuen Namen, um sie auf das Board zu bringen.",
"1fxf08k": "{0} liegt in diesem Browser. Veröffentliche es, um es auf das Board zu bringen, dann kannst du eine Zeit eintragen.",
"dru7ck": "{0} hat ein Layout, das noch nicht auf dem Board ist. Aktualisiere die Strecke, bevor du eine Zeit einträgst.",
