"1k5dzyz": "Sauberer Lauf",
"kkya0r": "Nichts, was der Erkenner benennen konnte. Ein Trick ist eine ganze Drehung um eine Achse oder eine Runde um etwas herum: ein Flip, ein Roll, 360 Grad Gieren, ein Powerloop unter einem Geländer. Um eine Ecke zu fliegen ist kein Trick und bringt mit Absicht nichts.",
"1y2kek1": "Zwei Minuten und nichts, was der Erkenner benennen konnte. Ein Trick ist eine ganze Drehung um eine Achse oder eine Runde um etwas herum: ein Flip, ein Roll, 360 Grad Gieren, ein Powerloop unter einem Geländer. Um eine Ecke zu fliegen ist kein Trick und bringt mit Absicht nichts.",
"m2e6mk": "Eine Trickart mehr",
"1rjo3vh": "Diesen Lauf eintragen schickt dem Board die Trickwertung, {0}. Das Board kennt bisher nur Tricks, also werden die Gaps, die knappen Vorbeiflüge und die Jagd in {1} hier gezählt und nicht dort.",
"1lipfcv": "Das Board nimmt nur Tricks, und dieser Lauf hat keinen benannt, also gibt es nichts einzutragen. Die Gaps, die knappen Vorbeiflüge und die Jagd in {0} werden hier gezählt.",
"nbri8l": "Kamerawinkel {0}°",
"1xqk8yk": "{0}: {1} {2}, zu wenig zum Fliegen.",
"182lfsh": "Keine Funke und kein Gamepad.",
"1w5xlhk": "Wähle den Stick für {0}: Drück, dann schieb den Stick, den du willst.",
"bwl76q": "Ein Joystick angeschlossen",
"1chzf7k": "Kein Joystick",
"exl51q": "Kein Joystick, den diese Seite fliegen kann.",
"18qtwr8": "Die gezeichneten Sticks folgen deiner gespeicherten Kalibrierung.",
"pjwruo": "Die gezeichneten Sticks zeigen, wie diese Seite ihn jetzt liest, und das ist geraten, bis du kalibrierst. Wenn sie deinen Händen nicht folgen, wähle ihn trotzdem und starte Sticks kalibrieren unter {0}.",
"utpvx5": "Diesen benutzen?",
