"p9ydk8": "Daumensticks",
"1lrz4zo": "Ein Daumen auf Glas hat etwa ein Viertel des Wegs eines Gimbals und nichts, das ihn zentriert, also sind die Zahlen unten sanfter angesetzt als die Standardwerte der Funke. Roll, Pitch und Gieren federn zurück, wenn du den Daumen hebst. Das Gas bleibt, wo du es gelassen hast, wie bei einer Funke.",
"iulg1q": "Eine Taste ist kein Stick. Hältst du sie, fährt der Stick auf 34 Prozent und bleibt dort bis etwa eine Dreiviertelsekunde, dann streckt er sich bei eineinviertel Sekunden auf voll. Die Rates unten sind also die, die eine FUNKE fliegen würde: Ein Tippen erreicht ungefähr ein Drittel davon, deshalb fühlt sich Tastaturflug fester an und greift langsamer, als die Zahlen sagen. Ein Gamepad oder eine Funke im USB-Joystick-Modus bekommt die ganze Kurve. Und ein Tastenrennen startet in Angle, das diese Kurve ignoriert: Tastaturrennen unter Quad, oder M im Flug, macht daraus Acro.",
"j83vdk": "Warte auf die Meldung der Funke. Beweg einen Stick.",
"pc5ckr": "Deine Funke aktualisiert {0} Mal pro Sekunde. Betaflight fliegt so oder so auf einem festen 250-Hz-Raster, das hier zeigt also, wie frisch der Wert in jedem dieser Frames ist.",
"tn3t15": "Das ist deine Bildrate, {0} pro Sekunde, und das heißt, dieser Browser liest die Funke nur einmal pro gezeichnetem Frame. Feedforward arbeitet mit der ÄNDERUNG zwischen Frames, ein Stick, der einmal pro Frame springt, fühlt sich also wie eine Reihe kleiner Stupser an statt wie ein Schub. Nichts in den Rates unten behebt das.",
"1iahfwq": "Diese Funke meldet etwa {0} Stufen über den vollen Weg eines Sticks, grob genug, um es bei hohen Rates zu spüren. Eine Funke mit feinerer USB-Meldung oder niedrigere Rates machen es weicher.",
"9fx780": "Funke, {0} Hz",
