"5ohxfa": "Dieser Browser hat die einzige Kopie, es lässt sich also nicht rückgängig machen. Die Zahlen bleiben auf dem Quad und fliegen weiter, nur das gespeicherte Profil verschwindet.",
"1b1e2ut": "Behalten",
