"1ffn2wt": "Jeder Teil des Baums ist offen. Die Sterne musst du dir weiter erfliegen.",
"t9ij2x": "Der Baum öffnet sich wieder Teil für Teil. Deine Medaillen sind alle noch da.",
"dc1bs4": "Jetzt ist nichts als bekannt markiert. Was du geflogen bist, bleibt geflogen.",
"bf5q3k": "Dieser Code ließ sich nicht lesen. Prüfe, ob er ganz kopiert wurde, von WFPV2 bis zum Ende.",
"19y24ww": "Geladen. Deine Karriere hat jetzt das Beste aus beiden: jede Medaille, jede Bestzeit.",
