"vej8um": "MACH EINE PAUSE",
"qkea4l": "Zu viele Versuche von hier. Warte zehn Minuten, oder bitte den Host um einen Einladungslink, der das Passwort überspringt.",
"1dwa1l2": "RÄUME SIND VOLL",
"10ug5qr": "Alle Räume, die das Board fassen kann, sind gerade offen. Versuch es bald wieder.",
"196i2s": "Kein Internet am Feld? Die Steam-Edition veranstaltet Rennabende im LAN.",
"l13tki": "NICHT IN DEINEM SPIEL",
"1kss8up": "{0} fliegt {1}, das diese Kopie von WebFPV nicht hat. Räume auf den Karten und Strecken in deinem Spiel funktionieren.",
"ow6oc8": "RÄUME SIND AUS",
"1b6p2oi": "Diese Kopie von WebFPV kann nicht online gehen, also sind Räume aus. Alles andere funktioniert wie bisher.",
"nrcnjt": "BEITRITT FEHLGESCHLAGEN",
"n8u5dn": "Das Board konnte diesen Raum nicht öffnen. Versuch es gleich noch einmal.",
"7acg4s": "Neu laden",
"1r5zwfr": "Zurück zu den Räumen",
"1hug03i": "WIE RÄUME DICH SCHÜTZEN",
"ilrx7u": "Niemand tritt dir uneingeladen bei",
"yeu8xo": "Ein Soloflug ist immer privat. Du trittst nur einem Raum bei, den du wählst, und in einen Raum kommen nur Leute, die sein Host einlädt oder die ihn gelistet finden. Ein Link fragt immer zuerst.",
"sgkomz": "Andere Piloten sehen",
"unh9nk": "Deinen Namen, deinen Avatar, deinen Quad und was du sagst. Ein Name, den die Wortliste stoppt, erscheint als erfundener. In einem schulsicheren Raum hat jeder einen erfundenen Namen, und gelistete, schulsichere und Streamer-Räume zeigen nie deine Internetadresse.",
"9kdcjv": "Chat",
"172cs5f": "Gelistete Räume reden nur in festen Sprüchen. Getippten Chat gibt es nur in privaten Räumen, deren Host ihn erlaubt, und das Board filtert ihn: keine Links, keine Nutzernamen, keine Telefonnummern.",
"azts1w": "Das Board sieht",
"14zgm64": "Deine Adresse, solange du verbunden bist, deinen Namen, die Teilenummern deines Avatars und den Chat des Raums, während er durchläuft. Es behält nichts davon, nachdem der Raum schließt.",
"wwt148": "Meldungen",
"3z05ce": "Eine Meldung schickt die letzten 20 Zeilen des Raums an den WebFPV-Admin, 30 Tage aufbewahrt. Das ist der einzige Chat, der je gespeichert wird.",
"182k9ke": "Schulen",
"kpcsmq": "Schulsichere Räume geben allen einen erfundenen Namen, nur festen Chat und verborgene Adressen.",
