"1hdv3x8": "Wähl einen Piloten, um ihm beim Fliegen zuzusehen, ihn stummzuschalten, zu melden, rauszuwerfen oder zu sperren, oder ihm den Raum zu übergeben. Stummschalten gilt nur für dich, und das Board erfährt es nie.",
"py5cx9": "Wähl einen Piloten, um ihm beim Fliegen zuzusehen, ihn stummzuschalten oder zu melden. Stummschalten gilt nur für dich, und das Board erfährt es nie.",
"7odbk8": "Die Person verlässt den Raum jetzt und kann in fünf Minuten zurückkommen.",
"vw2rc1": "Die Person geht jetzt, und dieser Browser kann nicht wieder beitreten, bis der Raum schließt.",
"12x7uqa": "Die Person bekommt die Host-Werkzeuge und du wirst Pilot. Sie kann sie zurückgeben.",
"12zldu4": "Ihr Quad zeigt stattdessen einen erfundenen Namen, für den Rest dieses Raums, egal was sie tippt.",
"1dlbaz1": "Ihr Quad zeigt stattdessen den erfundenen Namen des Raums, und dieses Konto kann seinen Namen in diesem Raum nicht mehr nutzen.",
