"p7xfuc": "Gesendet. {0} ist für dich stummgeschaltet. Der WebFPV-Admin liest jede Meldung.",
"147msxx": "Die letzten 20 Chatzeilen des Raums gehen mit der Meldung mit. Nur der WebFPV-Admin sieht sie, und nach 30 Tagen wird sie gelöscht.",
