"q4wvo7": "Bewegt wird {0}{1}. Wenn sich auf dem Bildschirm der falsche Stick bewegt hat, drück M. Wenn er sich falsch herum bewegt hat, drück R, um {2} umzukehren.",
"8d7906": "Enter oder Zuordnung speichern behält die Änderung. Escape lässt es, wie es war.",
"1y9oxv7": "Enter, Zuordnung speichern oder der Schalter, den du gerade zugewiesen hast. Escape bricht ab.",
"bcmm0k": "Enter oder Zuordnung speichern behält es. Escape bricht ab.",
"1b80rpt": "Diese Funke meldet keine Tasten, also kann ein Kanal die Taste sein. Kein Schalter übrig? Überspringen. So oder so zählt es als Druck, einen Stick eine Sekunde lang aus der Mitte zu halten.",
"x5yvt6": "Warte auf das Gas, das {0} Prozent zeigt. Es muss vor dem nächsten Schritt ganz unten sein. Wenn es beim Loslassen wieder hochfedert, halt es unten: Der letzte Schritt bietet an, die Null dort zu setzen, wo es ruht.",
"1hg708y": "Warte, bis der Menüschalter wieder dort ist, wo er war.",
"3qz4zi": "Warte, bis {0} in die Mitte zurückkommt.",
"14kvkwm": "Warte auf Achse {0}, die nicht dorthin zurückgekehrt ist, wo sie am Anfang war. Wenn das ein Schalter oder ein Drehregler ist, stell ihn zurück.",
"1ijq0x1": "Eine Richtung auf einmal. Diagonalen werden ignoriert.",
"nke3an": "Halt ihn dort. Diagonalen werden ignoriert.",
