"1kg7yxs": "Niemand zum Jagen. Runden werden weiter aufgezeichnet, sodass du beim späteren Einschalten deine Sitzung als Gegner hast, und das OSD zeigt an jedem Tor weiter deinen Abstand zu deiner besten Runde.",
"s97iq1": "Hole die drei schnellsten Runden vom Board.",
"1lvvitr": "Die drei schnellsten Runden des Boards sind da und fliegen ab der nächsten Runde mit.",
"i2wnsy": "Die drei schnellsten Runden des Boards fliegen neben dir, auf jeder Strecke, für die das Board Runden mit Geistern hat. Diese hat noch keine, oder das Board war nicht erreichbar, also fliegt stattdessen deine beste Runde.",
"y1qgdr": "Die {0} auf dem Board fliegen als durchscheinende Schrittmacher neben dir. Das OSD zeigt an jedem Tor deinen Abstand zur schnellsten.",
