"1r80dho": "Eine Karte, die du gebaut hast, ist für jeden Piloten anders, also bleiben ihre Läufe dem öffentlichen Board fern.",
"ib1esm": "Freiflug hat keine Uhr, also hat er keinen Platz auf dem Board. Stell Lauf im Freestyle-Bildschirm auf Wertung.",
"6kanhw": "Ein Lauf ohne Tricks ist keine Wertung.",
"1x7qf08": "Dieser Lauf hat die Testhaken benutzt, also ist er keine geflogene Wertung.",
"e1s1lm": "Das Gewicht hat sich während dieses Laufs geändert, also hat er kein einzelnes Gewicht fürs Board. Flieg ihn noch einmal mit einem Gewicht.",
"1gnhbo": "Tricks, die mit Luftgriff oder Motorleistung abseits von 100 gelandet wurden, bleiben dem öffentlichen Board fern. Stell beide zurück auf 100 und flieg ihn noch einmal.",
"10y1c4c": "Dieses Board ist für den Quad, für den diese Karte gebaut wurde. Ein Lauf mit dem anderen bleibt hier.",
"kr23p3": "Ein Lauf auf dem öffentlichen Board braucht einen Namen. Er bleibt in diesem Browser.",
