"6wc0zd": "Flugprotokoll gespeichert. {0} Zeilen über {1} s.",
"uoxhhu": "Eingetragene Zeiten und veröffentlichte Strecken tragen diesen Namen. Ihn zu ändern aktualisiert das Board für Strecken, die du aus diesem Browser veröffentlicht hast.",
