"pqk5pm": "Launch Control aus",
"6vog63": "Diese Seite fliegt keine hineingezogene Datei mehr. Wähl einen Tune im Menü und stell deine Rates unter Rates ein.",
"7giy7w": "Auto-Reset zum letzten Tor.",
"1fu1nz5": "Auto-Reset.",
