"19a3kr7": "Der Akku wird schwach. Reset für einen frischen.",
"ltlaqf": "Die 3D-Vorschau konnte nicht starten.",
"nzydht": "Rates fürs Daumenfliegen entschärft. 450 deg/s mit Expo. Du kannst sie im Rates-Bildschirm ändern.",
"1e62ufg": "Du fliegst mit {0}. Wähl Joystick in den Einstellungen, um einen anderen auszusuchen.",
