"cyw1pe": "Ein FPV-Rennsimulator im Browser. Der Controller ist Betaflight. Die Streckensprache kommt von Track Draw. Der Rest ist ein Pilot und die Leute, die ihn geflogen sind, bis er sich richtig anfühlte.",
"1sncokl": "Gemacht von",
"kai17": "Hat diesen Simulator, den Editor und das öffentliche Board gebaut. Hat dabei eine Horde aus Grok und Claude dirigiert.",
"1rju5ni": "Partner",
"10ax242": "Sie unterstützen WebFPV.",
"1fpu7yw": "Beta-Testpiloten",
"2sef6d": "Sie sind ihn geflogen, bis er sich wie ein Quad anfühlte.",
"lq4qk4": "Der Controller",
"152d3mr": "Die Rates, die PID-Schleife, die Filter, Feedforward, TPA, iterm relax, Airmode, Anti-Gravity. In diese Seite kompiliert, nicht neu geschrieben.",
"kfh8vm": "ist GPLv3, also ist es das hier auch. Der Flight-Controller-Bildschirm ist eine Hommage an",
"1ol0nlq": "10.10: Tabnamen, Felder aus 4.5.1 und das klassische Dunkelgrau mit Orange. Es ist nicht diese App. Kein Vue, kein MSP, kein iframe. Mit Dank an die Betaflight-Entwickler.",
"kwollz": "Die Streckensprache",
"91xq6y": "Der Editor ist inspiriert von",
"1v1kv66": ", von den niederländischen Drohnengöttern bei",
"1ffizjn": "Die RaceGOW5-Räume",
"ov7ihs": "Acht Strecken, sechs Erbauer, von den offiziellen Animationen abgelesen.",
"f0ewtp": "Serie und Animationen von",
"432t9y": "Die Horde",
"gw6sa5": "Geschrieben mit Grok. Gebaut mit Claude.",
"1m26mn1": "Grok von xAI. Viele der Zeilen, viele der Diskussionen und viel von der Sturheit beim Fluggefühl.",
"1i8y2kj": "Claude von Anthropic. Die andere Hälfte der Horde. Derselbe Mensch an den Sticks.",
"sskqzq": "Betaflight, Track Draw, Grok, Claude, Dutch Drone Squad und ihre Marken gehören ihren Inhabern. Die Kanalbilder gehören den Piloten. Sie hier zu verwenden ist eine Würdigung, keine Behauptung, dass sie diese Seite unterstützen. Die Marken der Partner gehören den Partnern und werden mit ihrer Zustimmung gezeigt. WebFPV ist freie Software unter",
