"1l302t4": "Einstellen:",
"1ra2hmr": "Triff einen Quad, um ihm Energie abzuziehen. Ist sie leer, platzt er, mit Konfetti. Jeder geplatzte Quad ist ein Punkt. Eine Rakete verfolgt einen Quad, sobald der Kasten rot wird.",
"abeo2g": "Kämpft!",
"43eacj": "Jeder Quad zieht ein Band hinter sich her. Flieg durch das Band eines anderen, um es zu kürzen. Halte deins von ihnen fern. Ganz weggeschnitten ist das Band weg und sein Pilot auch. Das letzte Band gewinnt.",
"1tj1cwp": "Fliegt!",
"11xt3fz": "Flieg tief hinter einer Ziege und sie läuft vor dir weg. Treib sie in die Garage von Heads. Jede Ziege gehört dem, der sie zuletzt hineingetrieben hat, also klau sie an der Tür.",
"1xzga63": "Hütet!",
"ckuwmm": "Wähl deine Seite und Bots nehmen alle anderen Plätze. Es geht in Sekunden los, ohne auf jemanden zu warten.",
"1t15mxw": "Minispiel",
"5ux909": "Wie willst du",
