"mhum2b": "GEGEN BOTS!",
"m2ey7b": "Du und so viele Bots, wie du willst. Es geht in Sekunden los, ohne auf jemanden zu warten.",
"9hddfa": "Spiel erstellen",
"dbjs0p": "Beitreten",
"2fhyvs": "Mit Freunden spielen",
"1bvgnvq": "Erstell ein privates Spiel und schick den Code, oder tipp den Code eines Freundes ein. Bots halten die leeren Plätze, und ein Freund, der beitritt, übernimmt einen.",
"lblpf4": "Echte Piloten",
"1joy1ch": "Jetzt mit Bots anstoßen. Ein anderer Pilot, der Schnelles Spiel wählt, übernimmt den Platz eines Bots. Nur vorgegebener Chat.",
"jzd9j1": "Mit Bots spielen",
"1hzmxtu": "Zurück",
"60bmqc": "Quad Ball, privates Spiel",
"fgk4f3": "Quad Ball, schnelles Spiel",
"65gil7": "Flieg in den Ball, um ihn zu treffen. Je härter du hineinfliegst, desto härter fliegt er. Pink verteidigt das Westtor und greift das Osttor an; Mint andersherum. Nach einem Tor haben alle ein paar Sekunden, um zum Anstoß zurückzufliegen.",
"j3lmwm": "Das Spiel erstellen",
"1clgctl": "Anstoß!",
"mja9lm": "Jag die Fahrer eine Minute lang. Nah, ruhig, das Bike in der Bildmitte, ein Whip oder ein großer Sprung und die Clipping-Zonen: alles gibt Punkte. Die beste Rolle gewinnt.",
"1srrqzv": "Film die Drift-Battles eine Minute lang. Nah, ruhig, das Auto in der Bildmitte, beide Autos eines Battles und die Clipping-Zonen: alles gibt Punkte. Die beste Rolle gewinnt.",
