"1nwt1ix": "Dieser Browser kann kein WebAssembly ausführen, und genau dazu ist der Flight Controller kompiliert.",
"pzazph": "Dieser Browser hat WebGL 1, aber nicht WebGL 2, und der Renderer braucht WebGL 2.",
"ohtzyz": "Dieser Browser gibt der Seite überhaupt keinen WebGL-Kontext, also kann nichts gezeichnet werden.",
"isa4xj": "Etwas, das die Seite brauchte, ist nicht angekommen. Der Renderer kommt von einem CDN, also kann ein Blocker oder ein Firmennetz ihn aufhalten.",
"r3utgs": "Dieses Gerät scheint offline zu sein.",
