"1iamjsl": "{0} hat hier {1} {2}, zu wenig zum Fliegen. Stell in EdgeTX den USB-Joystick-Modus auf Classic und steck sie dann neu an.",
"1m0xh9s": "Dein Joystick",
"1iyz2p7": "Keine Funke und kein Gamepad gefunden. Schließ eins an, stell es auf Joystick-Modus und lade neu.",
"awvaaq": "Keine Funke und kein Gamepad gefunden. Schließ eins an, stell es auf Joystick-Modus und beweg es dann.",
"1bcu86u": "{0}{1} ist angeschlossen, aber dieser Browser zeigt es mit {2} {3}, und zum Fliegen braucht es vier. Stell bei einer EdgeTX-Funke den USB-Joystick-Modus des Modells auf Classic, zieh die Funke dann ab und steck sie wieder an.",
"r0fr7u": "Ein Joystick",
"1k67jhh": "{0} kommt nicht im Sim an. Pausiere für die Stick-Hilfe.",
"1g3lqvf": "Noch kommt keine Funke und kein Gamepad in diesem Browser an. Schließ es an, stell es auf Joystick-Modus und beweg einen Stick: ein Browser zeigt einer Seite ein Pad erst, wenn sich daran etwas bewegt.",
"l55p9d": "Deine gespeicherte Kalibrierung liest {0} von einer Achse, die dieses Pad nicht hat, also {1} nichts. Es hat {2}. Sticks kalibrieren ordnet es neu zu, nach dem, was es wirklich sendet.",
"10cte0": "Achse {0} bewegt sich wie ein Stick, und nichts im Sim liest sie. Der Browser hat deinen Stick; der Sim hat ihn auf dem falschen Kanal. Sticks kalibrieren behebt das in etwa einer Minute.",
"13f86ul": "Achse {0} bewegt sich, und nichts im Sim liest sie. Wenn das der Stick ist, der nicht geht, legt Sticks kalibrieren ihn auf den richtigen Kanal.",
"3hxjne": "Das ist {0}, auf Achse {1}, und es kommt im Sim an.",
"4pid3q": "{0} hat sich wie ein Stick bewegt, und nichts im Sim liest {1}. Das ist ein Stick auf dem falschen Kanal, und Sticks kalibrieren behebt es.",
"13inlwb": "Beweg den Stick, der nicht geht, ganz bis an jedes Ende und schau auf die Balken.",
"2niqw0": "An der Funke: wähl beim Anstecken den USB-Joystick-Modus, bevor du diese Seite öffnest, und prüf das darauf gewählte Modell. Das Modell entscheidet, was jeder Kanal sendet, und ein neues oder leeres kann auf einem Stick gar nichts senden.",
"jem3gg": "Deine Funke kommt mit {0} Achsen an.",
"rr1z7d": "Wenn sich kein Balken bewegt: Windows",
"1j91r00": "Prüf, ob Windows den Stick sieht: drück Windows und R, tipp joy.cpl, drück Enter, wähl deine Funke und öffne Eigenschaften, dann beweg ihn. Wenn er sich dort bewegt und hier nicht, melde von diesem Bildschirm aus einen Bug und schreib das dazu.",
"1qj9g8y": "Wenn er sich dort auch nicht bewegt, sendet die Funke ihn nicht. Kalibrieren in diesem Windows-Fenster ändert nichts an dem, was ein Browser liest, also ist das nicht nötig.",
"1elsn67": "Wenn sich kein Balken bewegt: Mac",
"193sfmd": "macOS hat keinen eigenen Stick-Test, also sind diese Balken der Test. Wenn sich ein Stick hier in einem Browser bewegt und in einem anderen nicht, melde von diesem Bildschirm aus einen Bug und schreib dazu, in welchem.",
"1lg87ci": "Wenn sich kein Balken bewegt: Linux",
"fk484m": "jstest-gtk oder evtest zeigt, was die Funke sendet. Wenn sich der Stick dort bewegt und hier nicht, melde von diesem Bildschirm aus einen Bug und schreib das dazu.",
"1ftvq9i": "Wenn sich kein Balken bewegt",
"136r3g": "Du bist jetzt {0} Strecken geflogen.",
"1lxrdxg": "Das sind über zehn Minuten Freestyle.",
"mpbmvf": "Zwei weitere Regler lassen dich eigene Einstellungen ausprobieren.",
"1okdyz7": "Ein weiterer Regler lässt dich eigene Einstellungen ausprobieren.",
