"1k293vx": "Danke, das ist gezählt.",
"f6vn3r": "Zurückgenommen.",
"nagz31": "Das Board konnte diese Bewertung nicht annehmen.",
"9s1w1d": "Ein bis fünf Sterne, eine Bewertung pro Person. Du kannst sie ändern oder zurücknehmen. Piloten sehen den Durchschnitt neben dem Namen, und das Board kann die Besten zuerst zeigen.",
"fi2r1e": "Diesen Tune teilen",
"d8h2dl": "Stellt den Tune, den du fliegst, aufs öffentliche Board, mit einem kurzen Code, den jeder einfügen kann, um ihn zu fliegen. Das hier wird hochgeladen, und nur das:",
"86leg4": "Nicht enthalten: deine Grafik, deine Sticks und deine Funke, dein Flugmodus und deine Rundenzeiten. Einen Tune zu laden fasst das nie an.",
"1fdzjrk": "Gib diesem Tune einen Namen",
"69ns7i": "Ruhig und wie festgenagelt",
"5slhk5": "Ein Wort dazu (optional)",
"152173s": "Wofür er gut ist, was man zuerst probieren sollte.",
