"1kq6380": "Goldene Stunde: eine tiefe warme Sonne und lange violette Schatten. Das eigene Licht der Stadt.",
"r0wxsi": "Eine hohe weiße Sonne, kurze harte Schatten und ein tiefblauer Himmel.",
"ige15v": "Die Sonne am Horizont und ein violetter Himmel. Fenster, Straßenlaternen, Plakatwände und Automaten leuchten auf.",
