"wnpobs": "Ein Hof aus gesägten Betonplatten, mit einer gelben Linie ringsum.",
"yi1f2h": "Ein dunkler Parkplatz, mit Buchten und Pfeilen um alles herum, was du platzierst.",
"1a197nq": "Ein Rasen innerhalb des Bordsteins. Darauf sind keine Linien gemalt außer der Startbox.",
