"kt3x6o": "Nimmt das Teil und seine {0} Durchflüge aus der Strecke. Delete",
"c8ej9m": "Durchflug entfernen",
"14zit1c": "Nimmt diesen einen Durchflug aus der Runde und lässt das Teil stehen, wo es steht",
