"eq2s4x": "Alles Weitere dazu: der Name, die Größe, wo es auf den Zentimeter genau steht",
"1u9imh1": "Zieh eins, um sie zusammen zu bewegen. Q und E drehen sie. Die Pfeiltasten schieben sie ein Stück. Delete entfernt sie.",
