"1oadpln": "Schwebend",
"f4pdsq": "Hängt, wo es ist, mit nichts darunter: keine Beine, keine Füße. Trotzdem fest.",
"cipycl": "Ob ein erhöhtes Tor Beine bis zum Boden hat",
"g90jmu": "Im Rennen",
"18fqsdf": "Teil der Runde: beleuchtet, wenn es das nächste ist, gezählt und nummeriert",
"16rwdci": "Deko",
"1j14thj": "Bleibt gebaut und fest und ist kein Teil des Rennens: kein Hinweis, keine Zählung, keine Nummer. Es verlässt die Flugreihenfolge.",
"1utar14": "Ob die Runde durch dieses Tor geht",
