"gvwfs8": "Letztes Ende",
"1qjdyqg": "Das erste Ende ist dort, von wo die Wand gezogen wurde, also das Feld, das zuerst geflogen wird",
"1u4gca7": "Welche Enden einen Wimpel tragen, an ihrem äußeren Pfosten",
"1bi7jkv": "Um die Flagge herum hinein",
