"1q3r182": "Die Runde, Durchflug für Durchflug",
"1llf32i": "Ende",
"1qoay6c": "Ein Wegpunkt: hier biegt sich die Linie",
"q0b6ur": "{0}. Klick, um es anzusehen, zieh, um es zu bewegen, Delete nimmt es aus der Runde.",
"47t10a": "Flugreihenfolge: klick die Teile in der Reihenfolge an, in der du sie fliegst",
"l5kyq0": "Flugreihenfolge (N). Klick die Teile in der Reihenfolge an, in der du sie fliegst: ein weiterer Klick auf ein Teil ist ein weiterer Durchflug.",
"1l304es": "Dinge",
"1n9g4h1": "Festkörper",
