"1s93bks": "Wie groß das Grundstück ist, das Raster, die Tageszeit und der Boden",
"efchvk": "Alles über die Auswahl, das Grundstück und jede Warnung",
"1jm8ivx": "Panel schließen. Esc",
"1kpdcfp": "Länge",
"f2bx4s": "Durchflüge",
"a17t5z": "Neu anfangen",
"92kvsy": "Die Flugreihenfolge leeren und neu beginnen, Wegpunkte inklusive. Einmal Rückgängig holt sie zurück",
"1cfa0q1": "Eine Seite zum Drucken: wo jedes Teil steht, von einer Ecke aus gemessen, und welche Rohre und Fittings du kaufen musst",
"1osklvv": "Wie groß das Feld ist, und das Raster. Eine Strecke muss darin bleiben",
