"seajwm": "Das Panel mit der Flugreihenfolge, den Warnungen und dem Profil schließen. Esc",
"1l4fpy8": "Eine Hürde wird überflogen.",
"5ozvlp": "Flugreihenfolge: tipp auf das nächste Teil. Ein Teil noch einmal ist ein weiterer Durchflug.{0} Tipp noch einmal auf das Plus, um das Werkzeug wegzulegen.",
"1fj7bqd": "Flugreihenfolge: klick auf das nächste Teil. Ein Teil noch einmal ist ein weiterer Durchflug.{0} Backspace nimmt den letzten Durchflug weg. Esc legt das Werkzeug weg.",
"16bob4g": "Flugreihenfolge: klick auf das erste Teil, durch das die Runde geht, dann auf das nächste. Ein Teil noch einmal ist ein weiterer Durchflug.{0} Esc legt das Werkzeug weg.",
"1h3i156": "Tipp auf den Boden, um einen Würfel zu setzen: fünf Tore in einem Teil, gerade durchflogen in seiner Blickrichtung. Das Werkzeug bleibt aktiv. Tipp noch einmal auf Würfel, um es wegzulegen.",
"jihh0f": "Klick auf den Boden, um einen Würfel zu setzen: fünf Tore in einem Teil, gerade durchflogen in seiner Blickrichtung. Das Werkzeug bleibt aktiv. Rechtsklick oder Esc legt es weg.",
"1hjaiqs": "Leg es über Werkzeuge weg.",
"947ub9": "Tipp es links noch einmal an, um es wegzulegen.",
"ret7py": "Zieh über den Boden, um eine Reihe von zwei oder drei Toren zu setzen, 30 in auseinander. Ein Klick setzt ein Paar. Rechtsklick oder Esc legt das Werkzeug weg.",
"p956s2": "Klick auf zwei Punkte, um dazwischen zu messen. Ein Klick nahe an einem Tor oder einer Stange nimmt dessen Mitte. Rechtsklick oder Esc legt das Lineal weg.",
"6y6p5i": "Klick auf zwei Punkte, um dazwischen zu messen, in Metern. Ein Klick nahe an einem Teil nimmt dessen Mitte. Rechtsklick oder Esc legt das Lineal weg.",
"na57ja": "Zieh über den Boden, von dem Feld aus, das zuerst geflogen wird, um eine Wand zu setzen. Ein Tippen setzt drei. Eine Wand, dann wird das Werkzeug weggelegt.",
"1x41sn8": "Zieh über den Boden, von dem Feld aus, das zuerst geflogen wird, um eine Wand aus Toren zu setzen, die sich ihre Pfosten teilen, zwei bis sechs. Ein Klick setzt drei. Eine Wand, dann wird das Werkzeug weggelegt. Alt dreht sie frei.",
"3qzdj6": "Tipp",
"m8sun": "Klick",
"lzc7fh": "Die Formen sind unter Werkzeuge.",
"ybq1cu": "{0} dorthin, wo das Launch-Tor hin soll: ein waagerechtes Tor in 15 ft Höhe, von unten nach oben durchflogen, mit dem Hochziehen und dem Drücken über die Kuppe, die es fliegen, als Wegpunkte gelegt. Ein Tor, dann wird das Werkzeug weggelegt.",
"36gz3q": "{0} dorthin, wo die Stangenhürde hin soll: eine Stange, 10 ft breit und in 5 ft Höhe auf zwei Beinen, quer zur Strecke gedreht, und die Runde führt darüber. Die Karte sagt drunter oder knapp drüber. Eine Hürde, dann wird das Werkzeug weggelegt.",
"1onrj1y": "{0} dorthin, wo die Hürde hin soll: eine Tafel, 4 m lang und 1 m hoch, mit einer Flagge an jedem Ende, quer zur Strecke gedreht, und die Runde führt darüber. Eine Hürde, dann wird das Werkzeug weggelegt.",
"1cwij39": "{0} dorthin, wo das Aufwärtstor hin soll: um 45 Grad geneigt, mit der Unterkante auf 1,5 m, nach oben durchflogen. Ein Tor, dann wird das Werkzeug weggelegt.",
"18zqy2o": "Klick auf {0}, um es zu platzieren. Das Werkzeug bleibt aktiv, also platziert ein zweiter Klick ein weiteres. Rechtsklick oder Esc legt es weg.",
"gtzrzu": "Zieh es, um es zu bewegen. Zieh den Ring an seinem Fuß, um es zu drehen.",
"11yaxra": "Zieh es, um es zu bewegen. Zieh den Ring an seinem Fuß, um es zu drehen. Die Pfeiltasten schieben es ein Stück.",
"1k9grnp": "Unter Werkzeuge findest du die Teile, um mehr zu platzieren.",
"1weh0ir": "Wähl links ein Werkzeug, um mehr zu platzieren.",
"dmd4gm": "Klick ein Tor an, um es auszuwählen. Zieh an einer leeren Stelle über {0}, um dich umzusehen. Wähl links ein Werkzeug, um mehr zu platzieren.",
"13ytpyk": "Rechtsklick oder Esc legt es weg.",
"1sj82o4": "Rechtsklick oder Esc legt das Lineal weg.",
"gy64hi": "Ein Auto fährt auf einer Straße, und diese Karte hat noch keine. Leg zuerst eine mit dem Werkzeug Straße.",
"1wq4lkk": "Klick ein Teil an, um es auszuwählen. Zieh es, um es zu bewegen, und der Ring an seinem Fuß dreht es. Zieh auf leerem Boden, um dich umzusehen. Wähl links ein Werkzeug, um mehr zu platzieren.",
"1hid29q": "Öffne Werkzeuge und wähl {0}, dann tipp auf {1}.",
"102rg1e": "Oder fang mit einer fertigen RaceGOW-Strecke an und verschieb ein Tor.",
"90n8s5": "Mit einer RaceGOW-Strecke anfangen",
"pzcuyn": "Die acht Strecken von RaceGOW5, zum Öffnen und Ändern",
"twjbdg": "Oder öffne den Starter-Hof und mach ihn zu deinem.",
"14aviqa": "Mit dem Hof anfangen",
"deqy8p": "Die Karten, die mit dem Editor geliefert werden, und die, die du gespeichert hast",
"vmluuy": "Oder fang mit einer Strecke vom Board an und mach sie zu deiner. Rechtwinklig in der Leiste hält neue Tore an den Himmelsrichtungen, so wie ein Plan gezeichnet wird.",
"4d31w9": "Die Fünfzoll-Strecken auf Karten und Strecken, jede als deine eigene Kopie geöffnet",
"gdyprl": "Noch nichts in der Flugreihenfolge. Platzier ein Tor und es erscheint hier, mit den Rundenwerten und allen Warnungen.",
"4jbp44": "Höhenprofil",
"d388vx": "In der Reihenfolge",
"hwn39s": "Engster Bogen",
"s659t5": "Nichts zu melden. Die Linie geht in der richtigen Richtung durch jedes Element, innerhalb des Felds, frei von den Barrieren.",
"1jtc0ud": "Warnungen sind Hinweise. Nichts hier verhindert ein Speichern oder einen Export.",
